/**
 * De una liquidación de fruta interesan sobre todo dos datos: los kilos y el
 * precio por kilo. Se buscan en el texto ya leído, con cuidado de no confundir
 * el precio con el total.
 */
function guessLiquidacion(text) {
  if (!text) return null;
  const t = String(text).replace(/\s+/g, " ");
  const numero = "([0-9]{1,3}(?:\\.[0-9]{3})*(?:,[0-9]{1,3})?|[0-9]+(?:[.,][0-9]{1,3})?)";
  const kgHit =
    t.match(new RegExp("kilos?\\s*[:.]?\\s*" + numero, "i")) ||
    t.match(new RegExp(numero + "\\s*(?:kg|kilos?)\\b", "i"));
  const precioHit =
    t.match(new RegExp(numero + "\\s*(?:€|eur|euros?)\\s*(?:\\/|por|la)?\\s*(?:kg|kilo)", "i"));
  const kg = kgHit ? parseAmount(kgHit[1]) : null;
  const price = precioHit ? parseAmount(precioHit[1]) : null;
  return kg == null && price == null ? null : { product: "", kg, price, discounts: [] };
}

